// seed: tests/seed.user1.spec.ts
// Только чтение: даты — подменой часов браузера (_helpers/clock.ts); местоположение user1 (פתח תקווה) не меняется.
// Уборка: /home на реальном времени в новом контексте (generate_reminders пересоздаёт напоминания на сегодня).
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { openHomeAt, tefillinRows, duplicateTitles, restoreTodayReminders, TEFILLIN_TEXT } from '../_helpers/reminders';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  timezoneId: 'Asia/Jerusalem',
});

// 10:00 по Израилю — после עלות השחר и до שקיעה в любой из дат.
const DAYS: { day: string; label: string; tefillin: boolean }[] = [
  { day: '2026-10-04', label: 'вс, כ״ג תשרי — אסרו חג в Израиле', tefillin: true },
  { day: '2026-10-05', label: 'пн, כ״ד תשרי — будний день', tefillin: true },
  { day: '2026-10-09', label: 'пт — будний день', tefillin: true },
  { day: '2026-10-10', label: 'שבת', tefillin: false },
  { day: '2026-09-21', label: 'יום כיפור', tefillin: false },
  { day: '2026-09-28', label: 'חול המועד סוכות', tefillin: false },
  { day: '2027-04-22', label: 'יום טוב — פסח', tefillin: false },
  { day: '2027-04-25', label: 'חול המועד פסח', tefillin: false },
  { day: '2027-04-28', label: 'שביעי של פסח (יו״ט в Израиле)', tefillin: false },
  { day: '2027-04-29', label: 'כ״ב ניסן — אסרו חג в Израиле', tefillin: true },
  { day: '2027-06-13', label: 'вс после שבועות — будний день', tefillin: true },
];

test.describe('Напоминания', () => {
  test('RM-05 «הנחת תפילין» в «תזכורות מהירות» — в будни и אסרו חג есть, в שבת/יו״ט/חוה״מ/יום כיפור нет (Израиль) #3cc72778 @prod-safe @mobile', async ({ page, browser }, testInfo) => {
    try {
      for (const d of DAYS) {
        await test.step(`${d.day} 10:00 — ${d.label}: строка ${d.tefillin ? 'есть' : 'нет'}`, async () => {
          const rows = await openHomeAt(page, `${d.day}T10:00:00+03:00`, { expectDay: d.day });
          const tf = tefillinRows(rows);
          expect(tf, `строк «הנחת תפילין» на ${d.day}`).toHaveLength(d.tefillin ? 1 : 0);
          if (d.tefillin) {
            // источник: «מה רצוי» — «הנחת תפילין / אל תשכח להניח היום עד השקיעה», иконка в кружке справа (Figma 608:1389)
            expect(tf[0].sub).toBe(TEFILLIN_TEXT);
            expect(tf[0].lines).toBe(2);
            expect(tf[0].iconRight, 'кружок с иконкой справа от текста').toBe(true);
            expect(tf[0].overflow).toBe(false);
          }
          // по одной строке «הנחת תפילין» и «ראש חודש» (фикс c695450 — без дублей)
          expect(duplicateTitles(rows), 'дубли строк по типу').toEqual([]);
        });
      }
    } finally {
      await restoreTodayReminders(browser, testInfo);
    }
  });
});
